import {afterAll} from "bun:test";
const originalSet = globalThis.setTimeout;
const originalClear = globalThis.clearTimeout;
const timers = new Map();
globalThis.setTimeout = ((callback, ms, ...args) => {
 const stack = new Error().stack ?? "";
 const owner = stack.includes("semaphore.ts") ? "queue" : stack.includes("renderer.ts") ? "renderer" : stack.includes("phase-budgets.test.ts") ? "fixture" : "other";
 const row = {owner, ms, state:"pending"};
 const handle = originalSet(() => {row.state="fired"; callback(...args)}, ms);
 timers.set(handle,row);
 return handle;
}) as typeof setTimeout;
globalThis.clearTimeout = ((handle) => {
 const row=timers.get(handle);
 if(row?.state==="pending") row.state="cleared";
 originalClear(handle);
}) as typeof clearTimeout;
afterAll(() => console.log("NATIVE_TIMERS",JSON.stringify([...timers.values()])));
